// Serves /llms.txt with the two live usage figures substituted in.
//
// llms.txt is generated by scripts/build-i18n-seo.js from lib/seo/llms-txt.js and then
// served as a static file. Its "Live usage" section carries {{ROOMS_STAGED}} /
// {{USERS_SERVED}} placeholders rather than numbers, because the file is checked into git
// and a count that changes hourly has no business being committed. This middleware is
// where the placeholders become numbers.
//
// It has to be mounted AHEAD of express.static, for the same reason createTextAssetMiddleware
// is: express.static answers for anything that exists under public/, so the /llms.txt route
// in routes/public.js never runs (that file documents the same trap).

import fs from 'node:fs';
import path from 'node:path';
import { formatCount } from '../seo/live-stats.js';
import { ROOMS_STAGED_TOKEN, USERS_SERVED_TOKEN } from '../seo/llms-txt.js';
import { logger } from '../logger.js';
import { errorMessage } from '../errors.js';

/**
 * @param {string} publicDir absolute path to public/
 * @param {{ readPublicStats?: (() => import('../data/public-stats.js').PublicStats) | null }} [deps]
 * @returns {import('express').RequestHandler}
 */
export function createLlmsTxtMiddleware(publicDir, { readPublicStats = null } = {}) {
  const file = path.join(path.resolve(publicDir), 'llms.txt');

  return function serveLlmsTxt(req, res, next) {
    // No reader wired up (unit tests, or a caller that does not want this) — express.static
    // serves the file as-is, placeholders and all, which is at least honest.
    if (!readPublicStats) return next();
    if (req.method !== 'GET' && req.method !== 'HEAD') return next();
    if (req.path !== '/llms.txt') return next();

    let raw;
    try {
      raw = fs.readFileSync(file, 'utf8');
    } catch (err) {
      // Never 500 a crawler over this; express.static will 404 it if it really is missing.
      logger.warn(`[llms-txt] could not read llms.txt: ${errorMessage(err)}`);
      return next();
    }

    const { roomsStaged, usersServed } = readPublicStats();
    const body = raw
      .split(ROOMS_STAGED_TOKEN)
      .join(formatCount(roomsStaged))
      .split(USERS_SERVED_TOKEN)
      .join(formatCount(usersServed));

    res.type('text/plain; charset=utf-8');
    // Matches the .txt arm of express.static's setHeaders below it. res.send() derives the
    // ETag from THIS body, so a changed count changes the ETag and a conditional request
    // correctly gets a 200 instead of a stale 304.
    res.setHeader('Cache-Control', 'no-cache');
    return res.send(body);
  };
}
